 const integrationHealthButton = document.createElement('button'); integrationHealthButton.className = 'ghost-btn'; integrationHealthButton.id = 'integration-health-view'; integrationHealthButton.textContent = 'Integration health'; document.querySelector('#report-view').after(integrationHealthButton); integrationHealthButton.addEventListener('click', async () => { drawer.dataset.view = 'integration-health'; drawerTitle.textContent = 'Integration health'; recordSearch.value = ''; try { const health = await repository.getIntegrationHealth(); recordList.innerHTML = `<div class="report-period">Checked ${escapeHtml(new Date(health.generatedAt).toLocaleString())}</div><article class="report-card"><div><span class="record-id">OVERALL STATUS</span><h3>${escapeHtml(health.status)}</h3><p>Message queue: ${health.messages.pending} pending · ${health.messages.stale} stale · ${health.messages.failed} failed. Payment queue: ${health.payments.pending} pending · ${health.payments.failed} failed.</p></div></article>${Object.entries(health.checks).map(([key, value]) => `<article class="report-card"><div><span class="record-id">${escapeHtml(key)}</span><h3>${value ? 'Ready' : 'Needs attention'}</h3></div></article>`).join('')}`; } catch { recordList.innerHTML = '<div class="empty-state">Integration health is unavailable. Check your session or API.</div>'; } });
