const planDialog = document.createElement('dialog'); planDialog.className = 'workflow-dialog'; planDialog.innerHTML = '<button class="dialog-close" type="button" data-close-plan aria-label="Close">×</button><div class="dialog-kicker">RECURRING REVENUE</div><h2>New service plan</h2><p>Keep maintenance work on the calendar with a recurring customer agreement.</p><form id="new-plan-form"><label>Customer<select name="customerId" required><option value="">Loading customers…</option></select></label><label>Service<input name="service" required value="" /></label><label>Monthly amount<input name="amount" type="number" min="0.01" step="0.01" required value="149" /></label><label>Renewal date or note<input name="renewal" required value="Next month" /></label><div class="workflow-actions"><button class="ghost-btn" type="button" data-close-plan>Cancel</button><button class="primary-btn" type="submit">Create plan</button></div><p class="form-message" role="status" aria-live="polite"></p></form>'; document.body.append(planDialog); planDialog.querySelectorAll('[data-close-plan]').forEach((button) => button.addEventListener('click', () => planDialog.close()));
const planForm = planDialog.querySelector('#new-plan-form'); addPlanButton.addEventListener('click', async () => { const select = planForm.elements.customerId; select.innerHTML = '<option value="">Loading customers…</option>'; planForm.elements.service.value = tenant.serviceLabel + ' maintenance'; try { const customers = await repository.list('customers'); select.innerHTML = customers.length ? customers.slice(0, 100).map((item) => '<option value="' + escapeHtml(item.id) + '">' + escapeHtml(item.name) + ' · ' + escapeHtml(item.phone || 'No phone') + '</option>').join('') : '<option value="">Add a customer first</option>'; } catch { select.innerHTML = '<option value="">Customers unavailable</option>'; } planForm.querySelector('.form-message').textContent = ''; planDialog.showModal(); });
planForm.addEventListener('submit', async (event) => { event.preventDefault(); const submit = planForm.querySelector('[type="submit"]'); const message = planForm.querySelector('.form-message'); const amount = Number(planForm.elements.amount.value); if (!planForm.elements.customerId.value || !planForm.elements.service.value.trim() || !Number.isFinite(amount) || amount <= 0 || !planForm.elements.renewal.value.trim()) { message.textContent = 'Complete the customer, service, amount, and renewal fields.'; return; } submit.disabled = true; message.textContent = 'Creating plan…'; try { await repository.createPlan(planForm.elements.customerId.value, planForm.elements.service.value, amount, planForm.elements.renewal.value); planDialog.close(); showToast('Service plan created.'); openRecords('plans'); } catch { message.textContent = 'Could not create the service plan.'; submit.disabled = false; } });
