addPurchaseOrderButton.addEventListener('click', async () => { try { const materials = await repository.list('materials'); if (!materials.length) { showToast('Add an inventory item first.'); return; } const material = materials[0]; const vendor = window.prompt(`Vendor for ${material.name}`, 'Local supply house'); if (!vendor) return; const quantity = Number(window.prompt('Quantity to order', '10')); const unitCost = Number(window.prompt('Unit cost', String(material.unitCost))); if (!Number.isInteger(quantity) || quantity <= 0 || !Number.isFinite(unitCost) || unitCost < 0) return; await repository.createPurchaseOrder(material.id, vendor, quantity, unitCost); showToast('Purchase order created.'); openRecords('purchase-orders'); } catch { showToast('Could not create purchase order.'); } });
