customerDialog.querySelector('#new-customer-form').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const submit = form.querySelector('[type="submit"]'); const message = form.querySelector('.form-message'); submit.disabled = true; message.textContent = 'Saving…'; try { await repository.createCustomer(form.elements.name.value, form.elements.phone.value, form.elements.location.value || 'Address pending', form.elements.email.value); customerDialog.close(); showToast('Customer added.'); openRecords('customers'); } catch { message.textContent = 'Could not add customer. Check the phone, email, and duplicate contact details.'; submit.disabled = false; } });
document.querySelector('#add-asset').addEventListener('click', async () => { const customer = await chooseCustomer(); if (!customer) return; const name = window.prompt('Asset or equipment name'); if (!name) return; const serial = window.prompt('Serial number', 'Not recorded') || 'Not recorded'; const installed = window.prompt('Installed date', 'Date pending') || 'Date pending'; const warrantyThrough = window.prompt('Warranty through date (optional)', '') || ''; try { await repository.createAsset(customer.name, name, serial, installed, warrantyThrough, customer.id); showToast('Customer asset added.'); openRecords('assets'); } catch { showToast('Could not add customer asset. Check the warranty date format.'); } });
const estimateDialog = document.createElement('dialog');
estimateDialog.className = 'workflow-dialog';
estimateDialog.innerHTML = '<button class="dialog-close" type="button" data-close-estimate aria-label="Close">×</button><div class="dialog-kicker">ESTIMATES</div><h2>New estimate</h2><p>Build a clear quote from the customer record and your service catalog.</p><form id="new-estimate-form"><label>Customer<select name="customerId" required><option value="">Loading customers…</option></select></label><label>Service catalog<select name="catalogItemId"><option value="">Custom service</option></select></label><label>Service name<input name="service" required value="" /></label><label>Total amount<input name="amount" type="number" min="0.01" step="0.01" required value="500" /></label><fieldset><legend>Transparent pricing (optional)</legend><label>Subtotal<input name="subtotal" type="number" min="0.01" step="0.01" placeholder="Same as total" /></label><label>Discount<input name="discount" type="number" min="0" step="0.01" value="0" /></label><label>Tax rate (%)<input name="taxRate" type="number" min="0" max="30" step="0.01" value="0" /></label></fieldset><div class="workflow-actions"><button class="ghost-btn" type="button" data-close-estimate>Cancel</button><button class="primary-btn" type="submit">Create estimate</button></div><p class="form-message" role="status" aria-live="polite"></p></form>';
document.body.append(estimateDialog);
estimateDialog.querySelectorAll('[data-close-estimate]').forEach((button) => button.addEventListener('click', () => estimateDialog.close()));
const estimateForm = estimateDialog.querySelector('#new-estimate-form');
estimateForm.elements.catalogItemId.addEventListener('change', () => { const option = estimateForm.elements.catalogItemId.selectedOptions[0]; if (!option?.value) { estimateForm.elements.service.value = tenant.serviceLabel; estimateForm.elements.service.readOnly = false; estimateForm.elements.amount.value = '500'; return; } estimateForm.elements.service.value = option.dataset.name || option.textContent; estimateForm.elements.service.readOnly = true; estimateForm.elements.amount.value = option.dataset.amount || '500'; });
document.querySelector('#add-estimate').addEventListener('click', async () => { const customerSelect = estimateForm.elements.customerId; const catalogSelect = estimateForm.elements.catalogItemId; const serviceInput = estimateForm.elements.service; serviceInput.value = tenant.serviceLabel; serviceInput.readOnly = false; customerSelect.innerHTML = '<option value="">Loading customers…</option>'; catalogSelect.innerHTML = '<option value="">Custom service</option>'; try { const [customers, catalog] = await Promise.all([repository.list('customers'), repository.list('catalog')]); customerSelect.innerHTML = customers.length ? customers.slice(0, 100).map((item) => '<option value="' + escapeHtml(item.id) + '">' + escapeHtml(item.name) + ' · ' + escapeHtml(item.phone || 'No phone') + '</option>').join('') : '<option value="">Add a customer first</option>'; catalogSelect.innerHTML += catalog.map((item) => { const amount = item.priceFrom?.match(/[0-9]+(?:\\.[0-9]+)?/)?.[0] || '500'; return '<option value="' + escapeHtml(item.id) + '" data-name="' + escapeHtml(item.name) + '" data-amount="' + amount + '">' + escapeHtml(item.name) + ' · ' + escapeHtml(item.priceFrom || 'Price pending') + '</option>'; }).join(''); } catch { customerSelect.innerHTML = '<option value="">Customers unavailable</option>'; } estimateForm.querySelector('.form-message').textContent = ''; estimateDialog.showModal(); });
estimateForm.addEventListener('submit', async (event) => { event.preventDefault(); const submit = estimateForm.querySelector('[type="submit"]'); const message = estimateForm.querySelector('.form-message'); const amount = Number(estimateForm.elements.amount.value); const hasSubtotal = estimateForm.elements.subtotal.value.trim() !== ''; const subtotal = hasSubtotal ? Number(estimateForm.elements.subtotal.value) : null; const discount = Number(estimateForm.elements.discount.value || 0); const taxRate = Number(estimateForm.elements.taxRate.value || 0); if (!estimateForm.elements.customerId.value || !estimateForm.elements.service.value.trim() || !Number.isFinite(amount) || amount <= 0 || (hasSubtotal && (!Number.isFinite(subtotal) || subtotal <= 0 || !Number.isFinite(discount) || discount < 0 || discount > subtotal || !Number.isFinite(taxRate) || taxRate < 0 || taxRate > 30))) { message.textContent = 'Select a customer and enter valid estimate pricing.'; return; } submit.disabled = true; message.textContent = 'Creating estimate…'; try { const catalogItemId = estimateForm.elements.catalogItemId.value || null; const pricing = hasSubtotal ? { subtotal, discount, taxRate } : {}; await repository.createEstimate(estimateForm.elements.service.value, estimateForm.elements.service.value, amount, catalogItemId, estimateForm.elements.customerId.value, crypto.randomUUID(), pricing); estimateDialog.close(); showToast(catalogItemId ? 'Pricebook estimate created.' : 'Estimate created.'); openRecords('estimates'); } catch { message.textContent = 'Could not create estimate. Check the customer and amount.'; submit.disabled = false; } });
recordList.addEventListener('click', async (event) => { const preferencesButton = event.target.closest('[data-customer-preferences-action]'); if (preferencesButton) { const sms = window.prompt('SMS preference: type opt-out or allow', preferencesButton.dataset.smsOptOut === 'true' ? 'opt-out' : 'allow'); const email = window.prompt('Email preference: type opt-out or allow', preferencesButton.dataset.emailOptOut === 'true' ? 'opt-out' : 'allow'); if (!['opt-out', 'allow'].includes(sms) || !['opt-out', 'allow'].includes(email)) return; preferencesButton.disabled = true; try { await repository.updateCustomerPreferences(preferencesButton.dataset.customerId, { smsOptOut: sms === 'opt-out', emailOptOut: email === 'opt-out' }); const profile = await repository.getCustomerProfile(preferencesButton.dataset.customerId); renderProfile(profile); showToast('Contact preferences updated.'); } catch { showToast('Could not update contact preferences.'); preferencesButton.disabled = false; } return; } const tagsButton = event.target.closest('[data-customer-tags-action]'); if (tagsButton) { const raw = window.prompt('Customer tags, comma separated', tagsButton.dataset.customerTags || ''); if (raw === null) return; const tags = raw.split(',').map((tag) => tag.trim()).filter(Boolean); tagsButton.disabled = true; try { await repository.updateCustomerTags(tagsButton.dataset.customerId, tags); const profile = await repository.getCustomerProfile(tagsButton.dataset.customerId); renderProfile(profile); showToast('Customer tags updated.'); } catch { showToast('Could not update customer tags.'); tagsButton.disabled = false; } return; } const profileButton = event.target.closest('[data-customer-action]'); if (profileButton) { profileButton.disabled = true; try { const profile = await repository.getCustomerProfile(profileButton.dataset.customerId); drawer.dataset.view = 'profile'; drawerTitle.textContent = `${profile.customer.name} profile`; recordSearch.value = ''; renderProfile(profile); } catch { showToast('Customer profile unavailable.'); profileButton.disabled = false; } return; } const notificationButton = event.target.closest('[data-notification-action]'); if (notificationButton) { notificationButton.disabled = true; try { await repository.markNotificationRead(notificationButton.dataset.notificationId); showToast('Notification marked read.'); openRecords('notifications'); } catch { showToast('Could not update notification.'); notificationButton.disabled = false; } return; } const requestButton = event.target.closest('[data-request-action]'); if (requestButton) { const note = window.prompt('Resolution note', 'Owner follow-up completed.'); if (!note) return; requestButton.disabled = true; try { await repository.resolveRequest(requestButton.dataset.requestId, note); showToast('Customer request resolved.'); openRecords('requests'); } catch { showToast('Could not resolve customer request.'); requestButton.disabled = false; } return; } const locationButton = event.target.closest('[data-location-action]'); if (locationButton) { const address = window.prompt('Service address'); if (!address) return; const label = window.prompt('Location label', 'Service address') || 'Service address'; locationButton.disabled = true; try { await repository.createLocation(locationButton.dataset.customerId, label, address); const profile = await repository.getCustomerProfile(locationButton.dataset.customerId); renderProfile(profile); showToast('Customer location added.'); } catch { showToast('Could not add location.'); locationButton.disabled = false; } return; } const planButton = event.target.closest('[data-plan-action]'); if (planButton) { const time = window.prompt('Next recurring visit', 'Next month 9:00 AM'); if (!time) return; planButton.disabled = true; try { await repository.renewPlan(planButton.dataset.planId, time); showToast('Plan renewed and next visit scheduled.'); openRecords('plans'); } catch { showToast('Plan renewal unavailable.'); planButton.disabled = false; } return; } const leadButton = event.target.closest('[data-lead-action]'); if (leadButton) { const time = window.prompt('Schedule time', 'Tomorrow 9:00 AM'); if (!time) return; leadButton.disabled = true; try { await repository.convertLead(leadButton.dataset.leadId, time); showToast('Lead converted to a job.'); openRecords('leads'); } catch { showToast('Lead conversion unavailable.'); leadButton.disabled = false; } return; } const estimateButton = event.target.closest('[data-estimate-action]'); if (estimateButton) { estimateButton.disabled = true; try { if (estimateButton.dataset.estimateAction === 'approve') { await repository.updateEstimate(estimateButton.dataset.estimateId, 'approve'); showToast('Estimate approved.'); } else if (estimateButton.dataset.estimateAction === 'schedule') { const time = window.prompt('Schedule time', 'Tomorrow 9:00 AM'); if (!time) { estimateButton.disabled = false; return; } await repository.convertEstimate(estimateButton.dataset.estimateId, time); showToast('Estimate converted to a job.'); } else { await repository.createInvoice(estimateButton.dataset.estimateId); showToast('Invoice created.'); } openRecords('estimates'); } catch { showToast('Estimate workflow update unavailable.'); estimateButton.disabled = false; } return; } const invoiceButton = event.target.closest('[data-invoice-action]'); if (invoiceButton) { invoiceButton.disabled = true; try { await repository.payInvoice(invoiceButton.dataset.invoiceId); showToast('Payment recorded.'); openRecords('invoices'); } catch { showToast('Payment update unavailable.'); invoiceButton.disabled = false; } return; } const button = event.target.closest('[data-job-action]'); if (!button) return; if (button.dataset.jobAction === 'review-link') { button.disabled = true; try { const link = await repository.reviewLink(button.dataset.jobId); window.prompt('Copy this review link', new URL(link.url, window.location.href).href); } catch { showToast('Review link unavailable. Job must be completed.'); button.disabled = false; } return; } if (button.dataset.jobAction === 'customer-link') { button.disabled = true; try { const link = await repository.customerLink(button.dataset.jobId); window.prompt('Copy this customer portal link', new URL(link.url, window.location.href).href); } catch { showToast('Customer link unavailable.'); button.disabled = false; } return; } if (button.dataset.jobAction === 'link') { button.disabled = true; try { const link = await repository.technicianLink(button.dataset.jobId); window.prompt('Copy this technician link', new URL(link.url, window.location.href).href); } catch { showToast('Technician link unavailable. Assign a technician first.'); button.disabled = false; } return; } if (button.dataset.jobAction === 'priority') { const priority = window.prompt('Priority: Low, Normal, High, or Emergency', 'Normal'); if (!['Low', 'Normal', 'High', 'Emergency'].includes(priority)) return; button.disabled = true; try { await repository.updateJobPriority(button.dataset.jobId, priority); showToast(`Job priority set to ${priority}.`); openRecords('dispatch'); } catch { showToast('Could not update job priority.'); button.disabled = false; } return; } if (button.dataset.jobAction === 'complete') { const note = window.prompt('Completion note', 'Work completed and customer briefed.'); if (!note) return; button.disabled = true; try { await repository.completeJob(button.dataset.jobId, note); showToast('Job completed and timeline updated.'); openRecords('dispatch'); } catch { showToast('Job completion unavailable. Assign a technician first.'); button.disabled = false; } return; } let jobValue = button.dataset.jobValue; if (button.dataset.jobAction === 'reschedule') { try { const availability = await repository.getAvailability('', 14); const slots = (availability.slotOptions || []).slice(0, 24); const choice = window.prompt(`Choose an available appointment slot:\n${slots.map((slot, index) => `${index + 1}. ${slot.label}`).join('\n')}`, '1'); if (!choice || !slots[Number(choice) - 1]) return; jobValue = slots[Number(choice) - 1].id; } catch { showToast('Availability is unavailable.'); return; } } if (!jobValue) return; button.disabled = true; try { if (button.dataset.jobAction === 'reschedule') await repository.rescheduleJob(button.dataset.jobId, jobValue); else await repository.updateJob(button.dataset.jobId, button.dataset.jobAction, jobValue); showToast('Dispatch updated.'); openRecords('dispatch'); } catch { showToast('Dispatch update unavailable.'); button.disabled = false; } });
 recordList.addEventListener('click', async (event) => { const paymentRetryButton = event.target.closest('[data-payment-retry]'); if (paymentRetryButton) { paymentRetryButton.disabled = true; try { const result = await repository.retryPaymentIntent(paymentRetryButton.dataset.paymentRetry); showToast(result.duplicate ? 'Payment retry already queued.' : 'Payment retry queued.'); openRecords('payments'); } catch { showToast('Could not retry payment. Check the invoice balance.'); paymentRetryButton.disabled = false; } return; } const retryButton = event.target.closest('[data-message-retry]'); if (retryButton) { retryButton.disabled = true; try { const result = await repository.retryMessage(retryButton.dataset.messageRetry); showToast(result.duplicate ? 'Retry already queued.' : 'Message retry queued.'); openRecords('messages'); } catch { showToast('Could not retry message delivery.'); retryButton.disabled = false; } return; } const button = event.target.closest('[data-job-detail]'); if (button) { button.disabled = true; try { const detail = await repository.getJobDetail(button.dataset.jobDetail); drawer.dataset.view = 'job-detail'; drawerTitle.textContent = `${detail.job.service || 'Job'} detail`; recordSearch.value = ''; renderJobDetail(detail); } catch { showToast('Job detail unavailable.'); button.disabled = false; } return; } if (event.target.closest('[data-job-detail-back]')) openRecords('dispatch'); });
 document.querySelector('#drawer-refresh').addEventListener('click', async () => { if (drawer.dataset.view === 'reports') { try { renderReport(await repository.getReport()); } catch {} } else if (drawer.dataset.view) openRecords(drawer.dataset.view); });
recordSearch.addEventListener('input', async () => { const active = drawer.dataset.view; if (!active || active === 'reports') return; try { const [items, team] = active === 'dispatch' ? await Promise.all([repository.list(active, recordSearch.value), repository.list('team')]) : [await repository.list(active, recordSearch.value), []]; if (active === 'audit') renderAudit(items); else if (active === 'dispatch') { renderDispatchBoard(items, team); decorateDispatchWorkload(items); decorateDispatchRecommendations(); decorateDispatchNotifications(); decorateDispatchChecklists(); decorateDispatchDetails(); decorateDispatchNoShows(); decorateDispatchRebooks(); } else renderRecords(items, active); decorateMessageRetry(); decoratePaymentRetry(); } catch {} });
recordList.addEventListener('click', async (event) => { const purchaseButton = event.target.closest('[data-purchase-action]'); if (!purchaseButton) return; const input = window.prompt('Quantity received (leave blank for all remaining):'); if (input === null) return; const quantity = input.trim() ? Number(input) : null; if (quantity !== null && (!Number.isInteger(quantity) || quantity <= 0)) { showToast('Enter a positive whole-number quantity.'); return; } purchaseButton.disabled = true; try { await repository.receivePurchaseOrder(purchaseButton.dataset.purchaseId, quantity); showToast('Stock received and inventory updated.'); openRecords('purchase-orders'); } catch { showToast('Could not receive purchase order.'); purchaseButton.disabled = false; } });
recordList.addEventListener('click', async (event) => { const button = event.target.closest('[data-dispatch-recommend]'); if (!button) return; button.disabled = true; try { const result = await repository.recommendTechnicians(button.dataset.dispatchRecommend); const best = result.recommendations.find((item) => item.available) || result.recommendations[0]; if (!best) throw new Error('no recommendation'); const answer = window.confirm(`${best.technician}: ${best.reason}. Assign this technician?`); if (answer && best.available) { await repository.updateJob(button.dataset.dispatchRecommend, 'assign', best.technician); showToast(`Job assigned to ${best.technician}.`); openRecords('dispatch'); } else if (!best.available) showToast('Every technician has a conflict for this time.'); } catch { showToast('Could not generate a technician recommendation.'); } finally { button.disabled = false; } });
recordList.addEventListener('click', async (event) => { const button = event.target.closest('[data-dispatch-notify]'); if (!button) return; const template = window.prompt('Notification: confirmation, en_route, or completed', 'confirmation'); if (!['confirmation', 'en_route', 'completed'].includes(template)) return; const channel = window.prompt('Channel: SMS or Email', 'SMS'); if (!['SMS', 'Email'].includes(channel)) return; button.disabled = true; try { await repository.notifyJob(button.dataset.dispatchNotify, template, channel); showToast(`${channel} notification queued.`); } catch { showToast('Could not queue customer notification.'); } finally { button.disabled = false; } });
recordList.addEventListener('click', async (event) => { const button = event.target.closest('[data-dispatch-checklist]'); if (!button) return; const raw = window.prompt('Checklist steps, separated by commas', 'Arrived on site, Work performed and documented, Customer handoff completed'); if (!raw) return; const items = raw.split(',').map((item) => item.trim()).filter(Boolean); button.disabled = true; try { await repository.updateJobChecklist(button.dataset.dispatchChecklist, items); showToast('Job checklist updated.'); openRecords('dispatch'); } catch { showToast('Could not update the checklist. The job may already be underway.'); button.disabled = false; } });
