const decorateLeadStatusButtons = () => { if (drawer.dataset.view !== 'leads') return; recordList.querySelectorAll('.record-card').forEach((card) => { const id = card.querySelector('.record-id')?.textContent?.trim(); if (!/^.+_lead_\d{10,}$/.test(id || '') || card.querySelector('[data-lead-status-action]')) return; const actions = card.querySelector('.record-actions') || (() => { const created = document.createElement('div'); created.className = 'record-actions'; card.querySelector('div')?.append(created); return created; })(); ['Contacted', 'Qualified', 'Lost'].forEach((status) => { const button = document.createElement('button'); button.className = 'ghost-btn'; button.dataset.leadStatusAction = status; button.dataset.leadId = id; button.textContent = status; actions.append(button); }); }); };
const leadStatusObserver = new MutationObserver(decorateLeadStatusButtons);
leadStatusObserver.observe(recordList, { childList: true, subtree: true });
