const decoratePlanStatusButtons = () => { if (drawer.dataset.view !== 'plans') return; recordList.querySelectorAll('.record-card').forEach((card) => { const id = card.querySelector('.record-id')?.textContent?.trim(); const status = card.querySelector('.record-status')?.textContent?.trim(); if (!/^PLAN-\d{13,}$/.test(id || '')) { card.querySelectorAll('[data-plan-action], [data-plan-status-action]').forEach((button) => button.remove()); return; } if (card.querySelector('[data-plan-status-action]')) return; const actions = card.querySelector('.record-actions') || (() => { const created = document.createElement('div'); created.className = 'record-actions'; card.querySelector('div')?.append(created); return created; })(); if (['Active', 'Renewing soon'].includes(status)) { const pause = document.createElement('button'); pause.className = 'ghost-btn'; pause.dataset.planStatusAction = 'pause'; pause.dataset.planId = id; pause.textContent = 'Pause'; actions.append(pause); const cancel = document.createElement('button'); cancel.className = 'ghost-btn'; cancel.dataset.planStatusAction = 'cancel'; cancel.dataset.planId = id; cancel.textContent = 'Cancel plan'; actions.append(cancel); } else if (status === 'Paused') { const resume = document.createElement('button'); resume.className = 'ghost-btn'; resume.dataset.planStatusAction = 'resume'; resume.dataset.planId = id; resume.textContent = 'Resume'; actions.append(resume); } }); };
